import{_t as e,it as t,n,rt as r}from"./chunks/framework.C5Z6qjff.js";var i=JSON.parse(`{"title":"Die API verwenden","description":"","frontmatter":{"title":"Die API verwenden","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"de/api/index.md","filePath":"de/api/index.md"}`),a={name:`de/api/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="die-api-verwenden" tabindex="-1">Die API verwenden <a class="header-anchor" href="#die-api-verwenden" aria-label="Permalink to “Die API verwenden”">​</a></h1><p>Jede Funktion von OEA steht über die REST-API zur Verfügung. Die API ist im Vertrag <code>api/openapi.yaml</code> (OpenAPI 3.1) beschrieben; die Seiten dieses Kapitels werden daraus erzeugt und listen nur die Operationen, die diese Version implementiert. Die Beschreibungen der Operationen stammen aus dem englischen Vertrag.</p><h2 id="basis-url" tabindex="-1">Basis-URL <a class="header-anchor" href="#basis-url" aria-label="Permalink to “Basis-URL”">​</a></h2><p>Alle Operationen liegen unter <code>/api/v1</code> der Instanz, zum Beispiel <code>https://oea.example.org/api/v1/health</code>.</p><h2 id="authentisierung" tabindex="-1">Authentisierung <a class="header-anchor" href="#authentisierung" aria-label="Permalink to “Authentisierung”">​</a></h2><p>Es gibt keinen anonymen Zugriff, abgesehen von wenigen öffentlichen Operationen (Health, Setup, Anmeldung). Die Weboberfläche verwendet eine <strong>Sitzung</strong>:</p><ol><li>Melde dich mit <code>POST /auth/local/login</code> (lokales Systemadmin-Konto) oder über einen Identity-Provider an (<code>GET /auth/oidc/{providerId}/start</code>).</li><li>Die Sitzung ist das Cookie <code>__Host-OEA_SESSION</code>. Die Antwort der Anmeldung enthält ein <code>csrfToken</code>.</li><li>Sende das Token im Header <code>X-XSRF-TOKEN</code> mit jedem ändernden Request (<code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>).</li><li>Beende die Sitzung mit <code>POST /auth/logout</code>.</li></ol><p><a href="./../administration/#api-login">Für die Administration über die API anmelden</a> zeigt das mit <code>curl</code>.</p><h2 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to “Berechtigungen”">​</a></h2><p>Jede Operation nennt den Zugriff, den sie verlangt:</p><ul><li><strong>öffentlich</strong>: ohne Anmeldung</li><li><strong>jeder angemeldete Principal</strong>: jede Sitzung; Prüfungen am Objekt selbst können dazukommen</li><li><strong>Berechtigung</strong>: die genannten Berechtigungen sind nötig; <em>eine der Berechtigungen</em> bedeutet, dass eine davon genügt; <em>zusätzlich …, wenn: …</em> nennt Berechtigungen, die ein bestimmter Request zusätzlich braucht</li></ul><p>Berechtigungen kommen aus Rollen, siehe <a href="./../administration/roles-and-permissions">Rollen und Berechtigungen</a>.</p><h2 id="fehler" tabindex="-1">Fehler <a class="header-anchor" href="#fehler" aria-label="Permalink to “Fehler”">​</a></h2><p>Fehler werden als RFC 9457 Problem Details beantwortet (<code>application/problem+json</code>). Das Feld <code>type</code> benennt das Problem als <code>urn:oea:problem:&lt;name&gt;</code>, zum Beispiel <code>urn:oea:problem:validation-failed</code>; die Referenz listet die Problem-Typen pro Antwort.</p><ul><li><code>401</code>: nicht angemeldet, oder die Sitzung ist beendet</li><li><code>403</code>: eine nötige Berechtigung fehlt; die Antwort verrät nicht, welche</li><li><code>404</code>: das Objekt gibt es nicht – oder du darfst es nicht sehen</li><li><code>413</code>: der Request-Body ist zu groß (siehe <a href="./../administration/operations#request-size-limits">Größenlimits für Requests</a>)</li><li><code>422</code>: der Request ist wohlgeformt, aber nicht gültig</li></ul><h2 id="referenz" tabindex="-1">Referenz <a class="header-anchor" href="#referenz" aria-label="Permalink to “Referenz”">​</a></h2><p>Die Referenz hat eine Seite pro Bereich der API; öffne sie in der Seitenleiste.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};